const listClassesDueForAutoClose = `-- name: ListClassesDueForAutoClose :many
SELECT c.id
FROM classes c
JOIN academic_years ay ON ay.id = c.academic_year_id
WHERE c.status = 'active'
  AND ay.is_active
  AND attendance_day_is_effective(c.id, $1::date)
  AND NOT EXISTS (
    SELECT 1 FROM attendance_day_closures cl
    WHERE cl.class_id = c.id
      AND cl.attendance_date = $1::date
  )
ORDER BY c.name
`

